package com.studentgig.controller;
import com.studentgig.model.FreelanceJob; import com.studentgig.repository.FreelanceJobRepository; import org.springframework.web.bind.annotation.*; import jakarta.servlet.http.*; import java.util.*;
@RestController @RequestMapping("/api/freelance") public class FreelanceController {final FreelanceJobRepository r;FreelanceController(FreelanceJobRepository r){this.r=r;}private boolean logged(HttpSession s){return s.getAttribute("userId")!=null;}@GetMapping public Object all(HttpSession s){return logged(s)?r.findAll():Map.of("error","Please login first");}@PostMapping public Object create(@RequestBody FreelanceJob j,HttpSession s){Object id=s.getAttribute("userId");if(id==null)return Map.of("error","Please login");if("ADMIN".equals(String.valueOf(s.getAttribute("role"))))return Map.of("error","Use admin controls for platform management");j.clientId=(Long)id;return r.save(j);}@PutMapping("/{id}") public Object update(@PathVariable Long id,@RequestBody FreelanceJob j,HttpSession s){if(!logged(s))return Map.of("error","Please login");j.id=id;return r.save(j);}@DeleteMapping("/{id}")public Object del(@PathVariable Long id,HttpSession s){if(!logged(s))return Map.of("error","Please login");r.deleteById(id);return Map.of("message","Deleted");}}
